# ---------------------------------------------------------------------------
# Independent spec-level image validator (developed from PROTOCOL.md text).
# Returns (ok, represented_routes or None).
# ---------------------------------------------------------------------------
def _gb(word, pos, n):
    return (word >> pos) & ((1 << n) - 1)

def py_validate(image):
    try:
        root = image['root']
        f16 = image['front16']
        f64 = image['front64']
        cells = image['cells']
        banks = image['banks']
        pats = [int(x, 16) for x in image['bitmaps']]
        nexthops = [int(x) for x in image['nexthops']]
    except Exception:
        return (False, None)
    words = [[int(w, 16) for w in bank] for bank in banks]
    # physical shape
    total = 0
    for s in range(11):
        if not isinstance(cells[s], int) or not (0 <= cells[s] <= 131072): return (False, None)
        if len(words[s]) != (cells[s] + 1) // 2: return (False, None)
        total += len(words[s])
        if cells[s] & 1:
            if _gb(words[s][-1], 128, 128) != 0: return (False, None)
    if total > 65536: return (False, None)
    if len(nexthops) > 8192 or len(pats) > 8193: return (False, None)
    # fronts
    for lst, width in ((f16, 48), (f64, 0)):
        prev = -1
        for e in lst:
            k = int(e[0], 16)
            if k <= prev: return (False, None)
            prev = k
            st, cell = e[1], e[2]
            if not (0 <= st <= 10) or not (0 <= cell <= 131071): return (False, None)
            if cell >= cells[st]: return (False, None)
    for i in range(1, len(pats)):
        if pats[i - 1] >= pats[i]: return (False, None)

    at = {}          # (stage,cell) -> node
    slots = {s: [] for s in range(11)}
    used_pat = [False] * len(pats)
    stack = []
    if root is not None:
        stack.append((root[0], root[1], 0, 0, 0, 0))
    for e in f16:
        stack.append((e[1], e[2], 16, 16, int(e[0], 16) << 112, 0))
    for e in f64:
        stack.append((e[1], e[2], 64, 64, int(e[0], 16) << 64, 0))
    nodes = []
    while stack:
        (st, cell, origin, depth, region, expect) = stack.pop()
        if (st, cell) in at: return (False, None)
        if not (0 <= st <= 10): return (False, None)
        if cell >= cells[st]: return (False, None)
        word = words[st][cell >> 1]
        off = (cell & 1) * 128
        tp = _gb(word, off, 3)
        if not (1 <= tp <= 5): return (False, None)
        nat = 1 if tp in (1, 4) else 2
        slot = expect or nat
        if slot == 2:
            if cell & 1: return (False, None)
            if cell + 1 >= cells[st]: return (False, None)
            if nat == 1 and _gb(word, 128, 128) != 0: return (False, None)
        n = dict(type=tp, stage=st, cell=cell, slot=slot, origin=origin, depth=depth,
                 region=region, bmp=_gb(word, off + 3, 22), kids=[], inls=[],
                 bm=0, nibase=0, owned=0)
        kids = []
        if tp in (1, 2):
            bmid = _gb(word, off + 25, 16)
            n['nibase'] = _gb(word, off + 41, 22)
            if bmid >= len(pats): return (False, None)
            used_pat[bmid] = True
            n['bm'] = pats[bmid]
            if n['bm'] & 1: return (False, None)
            cnt = 2 if tp == 1 else 6
            seen_abs = False
            prev = -1
            first = True
            for j in range(cnt):
                r32 = _gb(word, off + 63 + 32 * j, 32)
                if r32 == (15 << 6):
                    seen_abs = True
                    continue
                if seen_abs: return (False, None)
                cst = _gb(r32, 6, 4)
                key = r32 & 0x3F
                ccell = r32 >> 10
                if cst >= 11 or cst >= st: return (False, None)
                if ccell >= cells[cst]: return (False, None)
                if (not first) and key <= prev: return (False, None)
                first = False
                prev = key
                kids.append((key, cst, ccell, False))
            if tp == 1:
                if _gb(word, off + 127, 1) != 0: return (False, None)
            else:
                if _gb(word, off + 255, 1) != 0: return (False, None)
                if not (3 <= len(kids) <= 6): return (False, None)
        elif tp == 3:
            bmid = _gb(word, off + 25, 16)
            n['nibase'] = _gb(word, off + 41, 22)
            if bmid >= len(pats): return (False, None)
            used_pat[bmid] = True
            n['bm'] = pats[bmid]
            if n['bm'] & 1: return (False, None)
            bulkbm = _gb(word, off + 63, 64)
            bulkbase = _gb(word, off + 127, 22)
            bulkstage = _gb(word, off + 149, 4)
            if _gb(word, off + 249, 7) != 0: return (False, None)
            nb = bin(bulkbm).count('1')
            if nb < 4: return (False, None)
            if bulkbase & 1: return (False, None)
            if bulkstage >= 11 or bulkstage >= st: return (False, None)
            if bulkbase + 2 * nb > cells[bulkstage]: return (False, None)
            directs = []
            seen_abs = False
            prev = -1
            first = True
            for j in range(3):
                r32 = _gb(word, off + 153 + 32 * j, 32)
                if r32 == (15 << 6):
                    seen_abs = True
                    continue
                if seen_abs: return (False, None)
                cst = _gb(r32, 6, 4)
                key = r32 & 0x3F
                ccell = r32 >> 10
                if cst >= 11 or cst >= st: return (False, None)
                if ccell >= cells[cst]: return (False, None)
                if (not first) and key <= prev: return (False, None)
                first = False
                prev = key
                if bulkbm & (1 << key): return (False, None)
                directs.append((key, cst, ccell, False))
            if len(directs) > 3: return (False, None)
            if not (7 <= nb + len(directs) <= 64): return (False, None)
            bi = 0
            for key in range(64):
                if not (bulkbm >> key) & 1: continue
                kids.append((key, bulkstage, bulkbase + 2 * bi, True))
                bi += 1
            kids.extend(directs)
            kids.sort()
        elif tp == 4:
            if _gb(word, off + 119, 9) != 0: return (False, None)
            frag = _gb(word, off + 25, 64)
            ln8 = _gb(word, off + 89, 8)
            hop = _gb(word, off + 97, 22)
            pl = _inline_prefix(frag, ln8, hop, origin, depth, region)
            if pl is None: return (False, None)
            n['inls'].append(pl)
        else:
            if _gb(word, off + 213, 43) != 0: return (False, None)
            for j in range(2):
                frag = _gb(word, off + 25 + 94 * j, 64)
                ln8 = _gb(word, off + 89 + 94 * j, 8)
                hop = _gb(word, off + 97 + 94 * j, 22)
                pl = _inline_prefix(frag, ln8, hop, origin, depth, region)
                if pl is None: return (False, None)
                n['inls'].append(pl)
            if n['inls'][0][0] == n['inls'][1][0] and n['inls'][0][1] == n['inls'][1][1]:
                return (False, None)
        n['kids'] = [(k[0], k[1], k[2], k[3]) for k in kids]
        at[(st, cell)] = n
        nodes.append(n)
        slots[st].append((cell, slot))
        for (key, cst, ccell, bulk) in kids:
            cr = region | (key << (128 - depth - 6))
            stack.append((cst, ccell, origin, depth + 6, cr, 2 if bulk else 0))
    # dense coverage
    for s in range(11):
        v = sorted(slots[s])
        pos = 0
        for (c, sz) in v:
            if c != pos: return (False, None)
            pos += sz
        if pos != cells[s]: return (False, None)
    # FIB extraction
    trie = {}
    count = [0]
    def tins(a, ln, hop):
        cur = trie
        for i in range(ln):
            b = (a >> (127 - i)) & 1
            if b not in cur: cur[b] = {}
            cur = cur[b]
        if None in cur: raise ValueError('dup')
        cur[None] = hop
        count[0] += 1
    ranges = []
    for n in nodes:
        if n['type'] <= 3:
            pop = bin(n['bm']).count('1')
            if pop == 0:
                if n['nibase'] != 0: return (False, None)
            else:
                if n['nibase'] + pop > len(nexthops): return (False, None)
                ranges.append((n['nibase'], n['nibase'] + pop))
            rank = 0
            bm = n['bm']
            while bm:
                p = (bm & -bm).bit_length() - 1
                bm &= bm - 1
                if p == 0: return (False, None)
                l = p.bit_length() - 1
                v = p - (1 << l)
                L = n['depth'] + l
                if not _origin_ok(n['origin'], L): return (False, None)
                a = n['region'] | (v << (128 - n['depth'] - l)) if l else n['region']
                try: tins(a, L, nexthops[n['nibase'] + rank])
                except ValueError: return (False, None)
                rank += 1
        else:
            for (a, L, hop) in n['inls']:
                try: tins(a, L, hop)
                except ValueError: return (False, None)
    if count[0] > 8192: return (False, None)
    ranges.sort()
    pos = 0
    for (a, b) in ranges:
        if a != pos: return (False, None)
        pos = b
    if pos != len(nexthops): return (False, None)
    if not all(used_pat): return (False, None)
    # ownership sizes (children have higher index? no: build parent map)
    children = {}
    for n in nodes:
        for (key, cst, ccell, bulk) in n['kids']:
            children.setdefault((n['stage'], n['cell']), []).append((cst, ccell))
    def owned_of(n):
        o = bin(n['bm']).count('1') if n['type'] <= 3 else len(n['inls'])
        for (cst, ccell) in children.get((n['stage'], n['cell']), []):
            o += owned_of(at[(cst, ccell)])
        n['owned'] = o
        return o
    # parents first order already ensures at[] has all; recursion with guard
    guard = set()
    def owned_of2(n):
        if (n['stage'], n['cell']) in guard: raise ValueError('cycle')
        guard.add((n['stage'], n['cell']))
        o = bin(n['bm']).count('1') if n['type'] <= 3 else len(n['inls'])
        for (cst, ccell) in children.get((n['stage'], n['cell']), []):
            o += owned_of2(at[(cst, ccell)])
        guard.discard((n['stage'], n['cell']))
        return o
    for n in nodes:
        o = owned_of2(n)
        if n['type'] <= 3:
            if o < 3: return (False, None)
        elif o != len(n['inls']):
            return (False, None)
    # BMP invariant
    def tbmp(region, depth):
        cur = trie
        found = None in cur
        best = cur.get(None)
        for i in range(depth):
            b = (region >> (127 - i)) & 1
            if b not in cur: break
            cur = cur[b]
            if None in cur:
                found = True
                best = cur[None]
        return (found, best)
    for n in nodes:
        f, b = tbmp(n['region'], n['depth'])
        want = b if f else BMP_NULL
        if n['bmp'] != want: return (False, None)
    routes = {}
    def collect(cur, pre, plen):
        if None in cur:
            routes[(plen, mask(pre, plen))] = cur[None]
        for bit in (0, 1):
            if bit in cur:
                collect(cur[bit], pre | (bit << (127 - plen)), plen + 1)
    collect(trie, 0, 0)
    return (True, routes)

def _origin_ok(origin, L):
    if origin == 0: return 0 <= L <= 16
    if origin == 16: return 17 <= L <= 64
    return 65 <= L <= 128

def _inline_prefix(frag, ln8, hop, origin, depth, region):
    if hop > HOP_MAX: return None
    if origin == 0:
        if ln8 > 16: return None
        L = ln8
        a = frag << 64
    elif origin == 16:
        if not (1 <= ln8 <= 48): return None
        L = 16 + ln8
        a = (region & 0xFFFF << 112) | (frag << 16)
    else:
        if not (1 <= ln8 <= 64): return None
        L = 64 + ln8
        a = (region & (0xFFFFFFFFFFFFFFFF << 64)) | frag
    if ln8 == 0:
        if frag != 0: return None
    elif ln8 < 64:
        if frag & ((1 << (64 - ln8)) - 1): return None
    if L < depth: return None
    if not _origin_ok(origin, L): return None
    if mask(a, depth) != mask(region, depth): return None
    return (a, L, hop)
